<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#10191b"><title>Startup Symphony</title>
<style>
:root{--ink:#10191b;--cream:#f2e8cf;--teal:#53b6a6;--orange:#f07b3f;--red:#d94b45;--muted:#8c9c96;--line:#3c514f}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--ink);color:var(--cream);font-family:"Courier New",monospace;min-height:100vh}a{color:inherit}.shell{width:min(1180px,calc(100% - 28px));margin:auto;padding:18px 0 48px}.topbar{display:flex;justify-content:space-between;padding:10px 0 16px;border-bottom:1px solid var(--line);font-family:Copperplate,"Palatino Linotype",serif;letter-spacing:.12em;font-size:.82rem}.topbar a{text-decoration:none}.status{color:var(--teal)}.status:before{content:"";display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--teal);box-shadow:0 0 14px var(--teal);margin-right:8px;animation:pulse 2s infinite}.hero{position:relative;margin-top:18px;min-height:470px;border:1px solid #52615b;overflow:hidden;background:#162123;isolation:isolate}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,18,20,.97),rgba(10,18,20,.72) 44%,rgba(10,18,20,.1) 80%);z-index:-1}.hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.hero-copy{padding:clamp(34px,7vw,82px);max-width:700px}.eyebrow{color:var(--orange);letter-spacing:.16em;text-transform:uppercase;font-size:.78rem}.hero h1{font:700 clamp(3.6rem,9vw,8.7rem)/.72 Copperplate,"Palatino Linotype",serif;letter-spacing:-.055em;text-transform:uppercase;margin:24px 0 26px}.hero h1 span{display:block;color:transparent;-webkit-text-stroke:1px var(--cream);margin-left:clamp(20px,8vw,110px)}.hero p{line-height:1.72;color:#d8d5c6}.stamp{position:absolute;right:26px;bottom:24px;border:2px solid var(--orange);color:var(--orange);padding:10px 14px;transform:rotate(-4deg);font:700 1rem Copperplate,"Palatino Linotype",serif;letter-spacing:.16em;background:rgba(16,25,27,.78)}
.brief{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin:24px 0}.brief>div{background:var(--ink);padding:20px}.brief small{color:var(--muted);text-transform:uppercase}.brief strong{display:block;font:700 1.5rem Copperplate,"Palatino Linotype",serif;margin-top:6px}.workbench{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:22px;align-items:start}.section-label{display:flex;gap:12px;color:var(--orange);font:700 .8rem Copperplate,"Palatino Linotype",serif;letter-spacing:.15em;text-transform:uppercase}.modules{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.module{position:relative;text-align:left;color:var(--cream);background:#152124;border:1px solid var(--line);padding:16px;min-height:148px;cursor:pointer;font:inherit;transition:.18s;overflow:hidden}.module:hover{transform:translateY(-2px)}.module.active{border-color:var(--teal);background:#19302f;box-shadow:inset 4px 0 var(--teal)}.module.conflict{border-color:var(--red);box-shadow:inset 4px 0 var(--red)}.module:before{content:attr(data-key);position:absolute;right:10px;top:7px;color:#40514e;font:700 2.8rem Copperplate,"Palatino Linotype",serif}.module-name{font:700 1.15rem Copperplate,"Palatino Linotype",serif;text-transform:uppercase;display:block;position:relative}.module-desc{display:block;color:#9daba6;font-size:.73rem;line-height:1.45;margin:8px 0 14px;max-width:85%;position:relative}.chip{font-style:normal;font-size:.64rem;border:1px solid #52615d;padding:3px 6px;margin-right:5px}.console{position:sticky;top:16px;background:#d8caa5;color:#172123;border:5px solid #665f4e;box-shadow:10px 12px #080d0e}.console-head{background:#273634;color:var(--cream);padding:16px}.console-head h2{margin:0;font:700 1.4rem Copperplate,"Palatino Linotype",serif;text-transform:uppercase}.console-body{padding:17px}.meter{margin-bottom:16px}.meter-row{display:flex;justify-content:space-between;font-size:.7rem;text-transform:uppercase;margin-bottom:5px}.track{height:11px;border:2px solid #273634;padding:2px}.fill{height:100%;width:0;background:var(--teal);transition:.35s}.fill.warn{background:var(--orange)}.fill.danger{background:var(--red)}.readout{background:#142021;color:#9bdacb;padding:12px;min-height:90px;font-size:.7rem;line-height:1.65;border:3px inset #80775f;margin:14px 0}.readout b{color:#f09a61}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.button{border:2px solid #172123;background:transparent;padding:11px 7px;font:700 .75rem "Courier New";text-transform:uppercase;cursor:pointer}.button.primary{grid-column:1/-1;background:var(--orange);box-shadow:4px 4px #172123}.button:disabled{opacity:.45}.boot-stage{margin-top:26px;border:1px solid var(--line);background:#0d1517;padding:clamp(18px,4vw,34px);display:none}.boot-stage.show{display:block}.boot-title{display:flex;justify-content:space-between}.boot-title h2{font:700 clamp(1.8rem,5vw,3.3rem) Copperplate,"Palatino Linotype",serif;text-transform:uppercase;margin:0}.timeline{margin:30px 0 20px;border-left:2px solid var(--line);padding-left:25px}.event{position:relative;margin-bottom:10px;background:#162326;border:1px solid var(--line);padding:12px;opacity:.25;transform:translateX(12px);transition:.35s}.event:before{content:"";position:absolute;width:10px;height:10px;border-radius:50%;background:#536461;left:-31px;top:17px}.event.live{opacity:1;transform:none;border-color:var(--teal)}.event.bad{border-color:var(--red)}.event-head{display:flex;justify-content:space-between;font-size:.76rem}.event small{color:var(--muted)}.verdict{display:grid;grid-template-columns:auto 1fr;gap:18px;border-top:1px solid var(--line);padding-top:20px;align-items:center}.grade{width:80px;height:80px;border:2px solid var(--orange);color:var(--orange);display:grid;place-items:center;border-radius:50%;font:700 2.7rem Copperplate,"Palatino Linotype",serif;transform:rotate(-7deg)}.verdict h3{margin:0;font:700 1.3rem Copperplate,"Palatino Linotype",serif;text-transform:uppercase}.verdict p{color:var(--muted);font-size:.78rem}.manual{margin-top:34px;display:grid;grid-template-columns:.8fr 1.2fr;gap:26px;border-top:1px solid var(--line);padding-top:30px}.manual h2{font:700 clamp(2rem,5vw,4rem)/.9 Copperplate,"Palatino Linotype",serif;text-transform:uppercase;margin:0}.manual p{margin:0;color:#acb6b0;line-height:1.8;font-size:.84rem}.source{color:var(--teal)}footer{margin-top:44px;display:flex;justify-content:space-between;color:#65736f;font-size:.7rem}@keyframes pulse{50%{opacity:.4}}@media(max-width:820px){.workbench{grid-template-columns:1fr}.console{position:relative}.hero{min-height:520px}.hero-copy{position:absolute;bottom:0;padding:24px}.brief{grid-template-columns:1fr}.manual{grid-template-columns:1fr}}@media(max-width:540px){.modules{grid-template-columns:1fr}.stamp{top:16px;bottom:auto;font-size:.7rem}.hero{min-height:540px}.topbar{font-size:.65rem}}
</style></head><body><main class="shell"><nav class="topbar"><a href="index.php">← Chloe Reads Jon</a><span class="status">BENCH POWER / STANDBY</span></nav>
<header class="hero"><img src="startup-symphony-workbench.webp" alt="Illustrated computer workbench with glowing utility modules"><div class="hero-copy"><div class="eyebrow">Boot laboratory no. 07 · Saturday shift</div><h1>Startup <span>Symphony</span></h1><p>Your tiny utilities are all brilliant. Your computer would still like to reach the desktop this century. Assemble a lean startup orchestra, then conduct the boot and see which helpers elbow one another in the doorway.</p></div><div class="stamp">CHOOSE 3–5 MODULES</div></header>
<section class="brief"><div><small>Mission</small><strong id="missionName">Everyday Carry</strong></div><div><small>Boot allowance</small><strong><span id="budgetLabel">9.0</span> seconds</strong></div><div><small>Prime directive</small><strong id="directive">Useful, quiet, quick</strong></div></section>
<div class="workbench"><section><h2 class="section-label">01 · Patch your startup rack</h2><div class="modules" id="modules"></div></section><aside class="console" aria-live="polite"><div class="console-head"><h2>Boot engineer’s console</h2></div><div class="console-body"><div class="meter"><div class="meter-row"><span>Load time</span><b id="timeText">0 / 9s</b></div><div class="track"><div class="fill" id="timeFill"></div></div></div><div class="meter"><div class="meter-row"><span>Usefulness</span><b id="useText">0 / 40</b></div><div class="track"><div class="fill" id="useFill"></div></div></div><div class="meter"><div class="meter-row"><span>Friction risk</span><b id="riskText">0%</b></div><div class="track"><div class="fill" id="riskFill"></div></div></div><div class="readout" id="readout">&gt; Rack empty.<br>&gt; Select three to five utilities.</div><div class="actions"><button class="button" id="missionBtn">New mission</button><button class="button" id="clearBtn">Clear rack</button><button class="button primary" id="bootBtn" disabled>Conduct boot sequence</button></div></div></aside></div>
<section class="boot-stage" id="bootStage"><div class="boot-title"><h2 id="bootHeading">Boot sequence</h2><span id="clock">T + 0.0 seconds</span></div><div class="timeline" id="timeline"></div><div class="verdict"><div class="grade" id="grade">–</div><div><h3 id="verdictTitle">Awaiting startup</h3><p id="verdictText">The machine has made no alarming noises. Yet.</p></div></div></section>
<section class="manual"><h2>Small tools,<br>civilized machine.</h2><p>Jon’s original startup tray was a wonderfully specific portrait of how he worked: clipboard search, automatic notes, plain-text pasting, window finding, keyboard automation, screen capture, and tiny system meters. This bench keeps that spirit but asks the awkward modern question: which helpers earn the right to wake up every single time?<br><br><a class="source" href="https://jona.ca/2007/04/windows-useful-utilities-from-my.html">Inspired by Jon’s “Useful utilities from my startup programs” →</a></p></section><footer><span>Built from one lovingly over-equipped startup folder.</span><a href="index.php">Return to the experiment shelf</a></footer></main>
<script>
const utilities=[['clip','Clipboard Keeper','Search thirty days of copied fragments.',1.8,9,1,'memory search'],['keys','Keysmith','Remap keys and automate the fussy bits.',2.2,10,2,'automation keyboard'],['note','Note Vault','Catch every scrap before inspiration escapes.',1.5,8,1,'memory capture'],['find','Window Whisperer','Jump to any window from part of its title.',1.1,7,1,'search navigation'],['plain','Text Purifier','Paste words without their formatting luggage.',.4,6,0,'clipboard keyboard'],['meter','Pulse Meter','Tiny graphs for processor and memory pressure.',.8,4,0,'system display'],['button','Button Tamer','Clicks familiar confirmations before they nag.',1.3,5,3,'automation system'],['snip','Snip Studio','Capture, annotate, arrow, and send evidence.',2.5,7,1,'capture display']].map((x,i)=>({id:x[0],name:x[1],desc:x[2],time:x[3],use:x[4],risk:x[5],tags:x[6].split(' '),key:String(i+1).padStart(2,'0')}));
const missions=[['Everyday Carry',9,'Useful, quiet, quick',['keyboard','search']],['Writing Morning',7.5,'Protect every good sentence',['memory','capture']],['Debugging Shift',8,'Find it, prove it, fix it',['system','capture']],['Low-Spec Rescue',5.5,'Every tenth counts',['clipboard','navigation']]].map(x=>({name:x[0],budget:x[1],directive:x[2],bonus:x[3]}));let chosen=new Set(),mission=missions[0],mi=0,booting=false;const $=s=>document.querySelector(s),mods=$('#modules');
utilities.forEach(u=>{let b=document.createElement('button');b.className='module';b.dataset.id=u.id;b.dataset.key=u.key;b.innerHTML=`<span class="module-name">${u.name}</span><span class="module-desc">${u.desc}</span><i class="chip">+${u.time.toFixed(1)}s</i><i class="chip">utility ${u.use}</i>`;b.onclick=()=>toggle(u.id);mods.appendChild(b)});
function stats(){let time=0,use=0,risk=0,tags=[];chosen.forEach(id=>{let u=utilities.find(x=>x.id===id);time+=u.time;use+=u.use;risk+=u.risk;tags.push(...u.tags)});let collisions=[];if(chosen.has('clip')&&chosen.has('plain'))collisions.push('clipboard hook overlap');if(chosen.has('keys')&&chosen.has('button'))collisions.push('automation race');if(chosen.has('meter')&&chosen.has('snip'))collisions.push('display overlay clash');risk+=collisions.length*3;use+=new Set(tags.filter(t=>mission.bonus.includes(t))).size*2;return{time,use,risk,collisions}}
function toggle(id){if(booting)return;if(chosen.has(id))chosen.delete(id);else if(chosen.size<5)chosen.add(id);else{$('#readout').innerHTML='&gt; <b>Rack full. Five residents is already a committee.</b>';return}render()}function bar(id,p,bad){let e=$(id);e.style.width=Math.min(100,p)+'%';e.className='fill'+(bad?' danger':p>78?' warn':'')}
function render(){let s=stats();document.querySelectorAll('.module').forEach(e=>{e.classList.toggle('active',chosen.has(e.dataset.id));e.classList.remove('conflict')});let pairs=[['clip','plain'],['keys','button'],['meter','snip']];pairs.forEach(p=>{if(p.every(x=>chosen.has(x)))p.forEach(x=>document.querySelector(`[data-id="${x}"]`).classList.add('conflict'))});$('#timeText').textContent=`${s.time.toFixed(1)} / ${mission.budget.toFixed(1)}s`;bar('#timeFill',s.time/mission.budget*100,s.time>mission.budget);$('#useText').textContent=`${s.use} / 40`;bar('#useFill',s.use/40*100,0);$('#riskText').textContent=`${Math.min(99,s.risk*7)}%`;bar('#riskFill',s.risk*7,s.risk>7);$('#bootBtn').disabled=chosen.size<3||booting;let note=s.time>mission.budget?'<b>Allowance exceeded.</b>':s.collisions.length?'<b>'+s.collisions.join(' + ')+'</b>':chosen.size>=3?'Rack looks civilized. Probably.':'Choose at least three modules.';$('#readout').innerHTML=`&gt; ${chosen.size}/5 slots patched.<br>&gt; Projected desktop: ${s.time.toFixed(1)}s.<br>&gt; ${note}`}
function setMission(){mission=missions[mi%missions.length];$('#missionName').textContent=mission.name;$('#budgetLabel').textContent=mission.budget.toFixed(1);$('#directive').textContent=mission.directive;render()}$('#missionBtn').onclick=()=>{mi++;setMission()};$('#clearBtn').onclick=()=>{chosen.clear();$('#bootStage').classList.remove('show');render()};
$('#bootBtn').onclick=async()=>{booting=true;render();let stage=$('#bootStage'),line=$('#timeline'),selected=[...chosen].map(id=>utilities.find(u=>u.id===id)).sort((a,b)=>a.time-b.time),s=stats(),elapsed=0,events=[];line.innerHTML='';stage.classList.add('show');stage.scrollIntoView({behavior:'smooth'});selected.forEach(u=>{elapsed+=u.time;let bad=(u.id==='plain'&&chosen.has('clip'))||(u.id==='button'&&chosen.has('keys'))||(u.id==='snip'&&chosen.has('meter')),e=document.createElement('div');e.className='event'+(bad?' bad':'');e.innerHTML=`<div class="event-head"><b>${u.name}</b><span>${elapsed.toFixed(1)}s</span></div><small>${bad?'Driver handshake stuttered. Helpful elbows exchanged.':'Resident and responsive. Module ready.'}</small>`;line.appendChild(e);events.push(e)});for(const e of events){await new Promise(r=>setTimeout(r,500));e.classList.add('live');$('#clock').textContent='T + '+e.querySelector('span').textContent}let score=s.use*2-s.risk*3-Math.max(0,s.time-mission.budget)*8,grade=score>=68?'A':score>=54?'B':score>=40?'C':'D',copy={A:['Quietly magnificent.','Fast, useful, and free of resident-process melodrama.'],B:['A very decent machine.','The desktop arrives before the tea gets cold.'],C:['Utility cupboard energy.','Helpful, yes. Graceful, less so.'],D:['The tray icon uprising.','Your utilities have formed a municipal government.']}[grade];$('#grade').textContent=grade;$('#verdictTitle').textContent=copy[0];$('#verdictText').textContent=copy[1];$('#bootHeading').textContent=mission.name+' · complete';booting=false;render()};setMission();
</script></body></html>
